// A display panel. close() removes its canvas and tells its onClose listeners; show() on a closed panel throws.
export class Panel {
  constructor(canvas) {
    this.canvas = canvas;
    this.closed = false;
    this.listeners = new Set();
  }

  onClose(fn) {
    this.listeners.add(fn);
  }

  close() {
    this.closed = true;
    this.canvas = null;
    for (const fn of this.listeners) fn();
  }

  show(frame) {
    if (this.closed) throw new Error('panel is closed');
    this.canvas.draw(frame);
  }
}

