// Play a sequence of frames in a panel.
export function play(panel, frames, fps) {
  let index = 0;
  const timer = setInterval(() => {
    panel.show(frames[index % frames.length]);
    index += 1;
  }, 1000 / fps);
  return { stop: () => clearInterval(timer) };
}
